            />
        </svg>
    )
}

DiscordIcon.displayName = "DiscordIcon"

export default DiscordIcon

import { forwardRef, type ComponentProps } from "react"

export interface PinterestIconProps extends Omit<ComponentProps<"svg">, "width" | "height"> {
    size?: number | string
}

export const PinterestIcon = forwardRef<SVGSVGElement, PinterestIconProps>(({ size = 24, className, ...props }, ref) => {
    return (
        <svg
            ref={ref}
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            width={size}
            height={size}
            className={className}
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            {...props}
        >
            <path d="M8 14.5c-3-4.5 1.462-8 4.5-8S18 8.154 18 12c0 3.038-2 5-4 5s-3-2-2.5-5m.5-2L9 21.5" />
            <path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2S2 6.477 2 12s4.477 10 10 10" />
        </svg>
    )
})

PinterestIcon.displayName = "PinterestIcon"

export default PinterestIcon

import { useId, type ComponentProps } from "react"

export interface BitbucketIconProps extends Omit<ComponentProps<"svg">, "width" | "height"> {
    size?: number | string
}

export const BitbucketIcon = ({ size = 24, className, style, ...props }: BitbucketIconProps) => {
    const gradientId = useId()

    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 128 128"
            width={size}
            height={size}
            fill="none"
            aria-hidden="true"
            focusable="false"
            className={className}
            style={{
                display: "inline-block",
                verticalAlign: "middle",
                flexShrink: 0,
                ...style,
            }}
            {...props}
        >
            <defs>
                <linearGradient
                    id={gradientId}
                    x1="28.593"
                    x2="16.672"
                    y1="14.226"
                    y2="23.532"
                    gradientTransform="scale(4)"
                    gradientUnits="userSpaceOnUse"
                >
                    <stop offset=".176" stopColor="#0052cc" />
                    <stop offset="1" stopColor="#2684ff" />
                </linearGradient>
            </defs>
            <path
                fill="#2684ff"
                d="M19.082 20c-1.918 0-3.355 1.758-3.039 3.516l12.95 79.289c.32 2.078 2.077 3.515 4.155 3.515h62.66c1.442 0 2.72-1.12 3.04-2.558l13.109-80.086c.316-1.918-1.121-3.516-3.039-3.516zM74.07 77.227H54.09l-5.278-28.293h30.215zm0 0"
            />
            <path
                fill={`url(#${gradientId})`}
                d="M107.64 48.934H78.868L74.07 77.227H54.09l-23.5 27.972s1.12.961 2.719.961h62.66c1.441 0 2.719-1.12 3.039-2.558zm0 0"
            />
        </svg>
    )
}

BitbucketIcon.displayName = "BitbucketIcon"

export default BitbucketIcon
